 dialog.setAttribute('aria-label',item.name+' unlocked');sparkles.setAttribute('aria-hidden','true');
 for(let i=0;i<12;i++){const star=node('span','✦');star.style.setProperty('--angle',(i*30)+'deg');sparkles.append(star);}
 art.innerHTML=item.slot==='buff'?pottedPlant(7,4):astronautBird({equipped:{[item.slot]:item.id}},0,'healthy');art.append(sparkles);
 const done=control('Continue exploring',()=>dialog.close(),'mission-primary');
 dialog.append(node('p','NEW UNLOCK','unlock-kicker'),node('h2',item.name),cosmeticPrice(item,true,'Unlocked'),art,node('p',item.description),done);dialogClose(dialog,()=>dialog.close());dialog.onclose=()=>dialog.remove();document.body.append(dialog);dialog.showModal();done.focus();
