 const main=node('div',null,'mission-content');root.append(status,main);
 async function act(action){
  if(busy)throw Error('One moment—your last action is saving.');busy=true;const run=generation,freshTask=action.type==='task'&&!missionSummary(state).done.includes(action.task),freshPurchase=action.type==='buy'&&!state.owned.includes(action.item);
  try{
   action={...action,id:action.id||crypto.randomUUID()};let next;
   if(user){const result=await api('/api/mission/action','POST',action);next=result.state;alias=result.alias;admin=result.admin===true;}
   else{next=applyMissionAction(state,action);localStorage.setItem('crewsafety-mission-guest',JSON.stringify(next));}
   if(run!==generation)throw Error('Account changed. Reload your mission.');state=next;state.equipped=missionEquipment(state.equipped);if(freshTask&&missionSummary(state).done.includes(action.task))celebrateTask(MISSION_TASKS.find(t=>t.id===action.task));if(freshPurchase&&state.owned.includes(action.item))celebrateUnlock(MISSION_SHOP.find(item=>item.id===action.item));return state;
  }finally{busy=false;}
 }
 function tell(message){status.textContent=message;}
 async function doAction(action,message){try{await act(action);tell(message);render();}catch(e){tell(e.message);}}
 async function refreshUser(next){
  document.querySelector('.unlock-dialog')?.close();document.querySelector('.costume-dialog')?.close();
  generation++;gameCleanup?.();gameCleanup=null;user=next;admin=false;alias='';
  if(!user){try{state=JSON.parse(localStorage.getItem('crewsafety-mission-guest'))||newMission();}catch{state=newMission();}state.equipped=missionEquipment(state.equipped);render();return;}
  const run=generation;try{const data=await api('/api/mission/state');if(run!==generation)return;state={...data.state,equipped:missionEquipment(data.state.equipped)};alias=data.alias;admin=data.admin===true;tell('Mission synced. Your private check-in answers stay on this device.');render();}catch(e){state=newMission();render();tell(e.message);}
 }
 window.addEventListener('crew-account-change',e=>refreshUser(e.detail));
 api('/api/auth/me').then(data=>{if(data.user&&!user)refreshUser(data.user);}).catch(()=>{});
 let careQueue=Promise.resolve();
