  const hero=node('div',null,'mission-hero'),pet=node('div',null,'mission-pet habitat-room');const stage=admin&&state.birdStage&&state.birdStage!=='auto'?state.birdStage:info.dust>=4?'needs-care':info.dust>0?'tired':'healthy';const dust=admin&&state.birdStage&&state.birdStage!=='auto'?({healthy:0,tired:3,'needs-care':7})[stage]:info.dust;pet.innerHTML='<div class="habitat-scene" aria-hidden="true">'+habitatArt+'</div><span class="habitat-label" aria-hidden="true">LUNAR OUTPOST</span>'+astronautBird(state,dust,stage);wirePet(pet,()=>speech);pet.setAttribute('aria-label','Pet '+(state.birdName||'Pip')+'. Tap or drag to play.');pet.querySelector('.astro-bird').setAttribute('aria-label',(state.birdName||'Pip')+', your astronaut bird. '+stage);
  const speech=node('p',stage==='needs-care'?'A quiet day for '+(state.birdName||'Pip')+'. A little care goes a long way.':stage==='tired'?'A little space dust. Any check-in will brighten '+(state.birdName||'Pip')+'’s day.':'Hey, crewmate. One small step is plenty.','bird-speech');pet.append(speech,node('small','Tap to play · drag and toss · gentle lunar hops','pet-hint'));
  const intro=node('div',null,'mission-intro');intro.append(node('p',(state.birdName||'Pip')+'’s expedition / '+(state.prestige+1),'mission-kicker'),node('h2','A little care.\nA whole universe.'),node('p','Take care of yourself. Help your little explorer reach Mars. Every honest check-in counts.','mission-description'));
