  if(!user)out.append(node('p','Browse the global rankings. Sign in to add your bird.'),control('Sign in',()=>document.getElementById('account-button').click(),'mission-primary'));
  if(user){const ownPoints=node('p');ownPoints.append(node('span',alias+' · '),admin?editableNumber('points','Leaderboard points',state.rankPoints):document.createTextNode(String(state.rankPoints)),document.createTextNode(' participation points'));out.append(ownPoints);}out.append(node('p','All registered accounts appear automatically, regardless of crew.','mission-muted'));
  if(admin)out.append(node('p','Click your bird’s points to edit them.','mission-muted'));
  const table=node('table');table.className='mission-ranking';const caption=node('caption','All registered birds');table.append(caption);const header=node('tr');for(const s of ['Rank','Bird','Owner','Points'])header.append(node('th',s));const thead=node('thead');thead.append(header);table.append(thead);const body=node('tbody');table.append(body);out.append(table);
  try{const result=await api('/api/mission/leaderboard');if(!out.isConnected)return;caption.textContent=result.demo?'Demo crew · top 10':'All registered birds';if(!result.rows.length)out.append(node('p','No registered birds yet.'));for(const r of result.rows){const tr=node('tr');for(const v of [r.rank,r.alias,r.owner||'—'])tr.append(node('td',String(v)));const points=node('td');points.append(admin&&r.self?editableNumber('points','Leaderboard points',r.points):document.createTextNode(String(r.points)));tr.append(points);body.append(tr);}if(result.self&&!result.rows.some(r=>r.self)){const mine=node('div',null,'personal-rank');const detail=node('p');detail.append(document.createTextNode(`#${result.self.rank} · ${result.self.alias} · `),admin?editableNumber('points','Leaderboard points',result.self.points):document.createTextNode(String(result.self.points)),document.createTextNode(' points'));mine.append(node('strong','Your rank'),detail);out.append(mine);}}catch(e){out.append(node('p',e.message));}
